"""Random lines for the word counter.

The word count of each line is fixed when the line is built -- the builders
join a known number of words with separators -- so the awkward shapes (runs of
spaces, padding at the ends, a tab instead of a space) are guaranteed to turn
up rather than being left to chance.
"""

LETTERS = "abcdefghijklmnopqrstuvwxyz"
PUNCTUATION = ",.!?;:"


def generate(rng, count):
    builders = (_plain_sentence, _wide_gaps, _padded_ends, _one_word)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _word(rng):
    return "".join(rng.choice(LETTERS) for _ in range(rng.randint(1, 8)))


def _plain_sentence(rng, index):
    words = [_word(rng) for _ in range(rng.randint(2, 6))]
    words[-1] += rng.choice(PUNCTUATION)
    return _case("a plain sentence #%d" % index, " ".join(words),
                 "Punctuation belongs to the word it is stuck to.")


def _wide_gaps(rng, index):
    words = [_word(rng) for _ in range(rng.randint(2, 5))]
    text = words[0]
    for word in words[1:]:
        gap = "\t" if rng.random() < 0.3 else " " * rng.randint(2, 5)
        text += gap + word
    return _case("wide gaps #%d" % index, text,
                 "A run of spaces, or a tab, separates one pair of words.")


def _padded_ends(rng, index):
    words = [_word(rng) for _ in range(rng.randint(1, 4))]
    text = " " * rng.randint(1, 3) + " ".join(words) + " " * rng.randint(1, 3)
    return _case("padded at both ends #%d" % index, text,
                 "The spaces at either end are not words and do not start one.")


def _one_word(rng, index):
    return _case("a single word #%d" % index, _word(rng))
